@@ -0,0 +1,138 @@
+'use strict';
+/**
+ * request-compat: a small, dependency-free replacement for the deprecated `request`
+ * package, built on native fetch (Node 18+). Generated by Revenant (recipe request-to-fetch).
+ *
+ * Supported: request(uri|options, [options], callback), request.get/post/put/patch/del/head,
+ * options: uri/url, method, qs, headers, body, json, form, auth, timeout, followRedirect,
+ * encoding: null. Not supported (flagged by Revenant as TODO): streams / .pipe(),
+ * cookie jars, multipart, nested qs objects, proxies, retries.
+ */
+
+function encodeQuery(qs) {
+  const parts = [];
+  for (const key of Object.keys(qs)) {
+    const value = qs[key];
+    if (value === undefined) continue;
+    if (Array.isArray(value)) {
+      value.forEach((v, i) => parts.push(encodeURIComponent(key + '[' + i + ']') + '=' + encodeURIComponent(String(v))));
+    } else {
+      parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
+    }
+  }
+  return parts.join('&');
+}
+
+function request(uri, options, callback) {
+  let opts = typeof uri === 'object' && uri !== null ? Object.assign({}, uri) : { uri: uri };
+  if (typeof options === 'function') callback = options;
+  else if (options && typeof options === 'object') opts = Object.assign(opts, options);
+  if (typeof opts.callback === 'function' && !callback) callback = opts.callback;
+
+  const target = opts.uri || opts.url;
+  if (!target) {
+    const err = new Error('options.uri is a required argument');
+    if (callback) { queueMicrotask(function () { callback(err); }); return { abort: function () {} }; }
+    throw err;
+  }
+  let href = String(target);
+  if (opts.qs) {
+    const q = encodeQuery(opts.qs);
+    if (q) href += (href.indexOf('?') === -1 ? '?' : '&') + q;
+  }
+
+  const method = (opts.method || 'GET').toUpperCase();
+  const headers = {};
+  Object.keys(opts.headers || {}).forEach(function (k) { headers[k.toLowerCase()] = String(opts.headers[k]); });
+
+  let body;
+  if (opts.form !== undefined) {
+    body = typeof opts.form === 'string' ? opts.form : encodeQuery(opts.form);
+    if (!headers['content-type']) headers['content-type'] = 'application/x-www-form-urlencoded';
+  } else if (opts.json !== undefined && opts.json !== true && opts.json !== false) {
+    body = JSON.stringify(opts.json);
+    if (!headers['content-type']) headers['content-type'] = 'application/json';
+  } else if (opts.body !== undefined) {
+    if (opts.json === true && typeof opts.body !== 'string' && !Buffer.isBuffer(opts.body)) {
+      body = JSON.stringify(opts.body);
+      if (!headers['content-type']) headers['content-type'] = 'application/json';
+    } else {
+      body = opts.body;
+    }
+  }
+  if (opts.json && !headers.accept) headers.accept = 'application/json';
+  if (opts.auth) {
+    const user = opts.auth.user || opts.auth.username || '';
+    const pass = opts.auth.pass || opts.auth.password || '';
+    headers.authorization = 'Basic ' + Buffer.from(user + ':' + pass).toString('base64');
+  }
+
+  const controller = new AbortController();
+  let timer;
+  if (opts.timeout) timer = setTimeout(function () { controller.abort(); }, opts.timeout);
+
+  const promise = fetch(href, {
+    method: method,
+    headers: headers,
+    body: method === 'GET' || method === 'HEAD' ? undefined : body,
+    redirect: opts.followRedirect === false ? 'manual' : 'follow',
+    signal: controller.signal,
+  }).then(function (res) {
+    return res.arrayBuffer().then(function (ab) {
+      if (timer) clearTimeout(timer);
+      const buf = Buffer.from(ab);
+      const resHeaders = {};
+      res.headers.forEach(function (v, k) { resHeaders[k] = v; });
+      let parsed = opts.encoding === null ? buf : buf.toString('utf8');
+      if (opts.json && typeof parsed === 'string') {
+        try { parsed = JSON.parse(parsed); } catch (e) { /* request leaves unparseable bodies as strings */ }
+      }
+      const response = {
+        statusCode: res.status,
+        statusMessage: res.statusText,
+        headers: resHeaders,
+        body: parsed,
+        request: { uri: new URL(href), method: method },
+      };
+      return { response: response, body: parsed };
+    });
+  });
+
+  if (callback) {
+    promise.then(
+      function (r) { callback(null, r.response, r.body); },
+      function (e) { if (timer) clearTimeout(timer); callback(e); }
+    );
+  }
+  return { abort: function () { controller.abort(); }, then: undefined, promise: promise };
+}
+
+['get', 'post', 'put', 'patch', 'head', 'delete'].forEach(function (m) {
+  request[m] = function (uri, options, callback) {
+    const o = typeof uri === 'object' && uri !== null ? Object.assign({}, uri) : { uri: uri };
+    if (typeof options === 'function') callback = options;
+    else if (options && typeof options === 'object') Object.assign(o, options);
+    o.method = m.toUpperCase();
+    return request(o, callback);
+  };
+});
+request.del = request.delete;
+request.defaults = function (defaults) {
+  const wrapped = function (uri, options, callback) {
+    const o = typeof uri === 'object' && uri !== null ? Object.assign({}, defaults, uri) : Object.assign({}, defaults, { uri: uri });
+    if (typeof options === 'function') return request(o, options);
+    return request(Object.assign(o, options), callback);
+  };
+  ['get', 'post', 'put', 'patch', 'head', 'delete'].forEach(function (m) {
+    wrapped[m] = function (uri, options, callback) {
+      const o = typeof uri === 'object' && uri !== null ? Object.assign({}, uri) : { uri: uri };
+      if (typeof options === 'function') callback = options;
+      else if (options && typeof options === 'object') Object.assign(o, options);
+      o.method = m.toUpperCase();
+      return wrapped(o, callback);
+    };
+  });
+  return wrapped;
+};
+
+module.exports = request;
