// Differential property-based tests: `request` (old) vs request-compat on native fetch (new).
// Generated by Revenant, recipe request-to-fetch. Run with: npx vitest run
import { createServer, type Server } from "node:http";
import { createRequire } from "node:module";
import type { AddressInfo } from "node:net";
import fc from "fast-check";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

const require = createRequire(import.meta.url);
const oldRequest = require("request");
const newRequest = require("./request-compat.cjs");

type Cb = (err: unknown, res: { statusCode: number; body: unknown }, body: unknown) => void;
const call = (impl: (o: object, cb: Cb) => void, opts: object) =>
  new Promise<{ status: number; body: unknown }>((resolve, reject) =>
    impl(opts, (err, res, body) => (err ? reject(err) : resolve({ status: res.statusCode, body }))),
  );

let server: Server;
let base = "";

beforeAll(async () => {
  server = createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => {
      const url = new URL(req.url ?? "/", "http://x");
      const status = Number(url.searchParams.get("status") ?? 200);
      res.writeHead(status, { "content-type": "application/json", "x-echo": "1" });
      res.end(
        JSON.stringify({
          method: req.method,
          path: url.pathname,
          query: req.url?.split("?")[1] ?? "",
          contentType: req.headers["content-type"] ?? null,
          custom: req.headers["x-prop"] ?? null,
          body: Buffer.concat(chunks).toString("utf8"),
        }),
      );
    });
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
afterAll(() => new Promise<void>((r) => server.close(() => r())));

const word = fc.stringMatching(/^[a-z0-9]{1,8}$/);
const scalar = fc.oneof(word, fc.integer({ min: 0, max: 9999 }));

describe("request vs request-compat (differential)", () => {
  it("GET with query strings returns identical status and body", async () => {
    await fc.assert(
      fc.asyncProperty(word, fc.dictionary(word, scalar, { maxKeys: 4 }), fc.constantFrom(200, 201, 404, 500), async (seg, qs, status) => {
        const opts = { uri: `${base}/${seg}`, qs: { ...qs, status }, json: true };
        const [a, b] = [await call(oldRequest, opts), await call(newRequest, opts)];
        expect(b).toEqual(a);
      }),
      { numRuns: 100 },
    );
  });

  it("POST/PUT/PATCH with JSON bodies and custom headers match", async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom("POST", "PUT", "PATCH"),
        fc.dictionary(word, fc.oneof(word, fc.integer(), fc.boolean()), { maxKeys: 4 }),
        word,
        async (method, payload, header) => {
          const opts = { uri: `${base}/echo`, method, body: payload, json: true, headers: { "X-Prop": header } };
          const [a, b] = [await call(oldRequest, opts), await call(newRequest, opts)];
          expect(b).toEqual(a);
        },
      ),
      { numRuns: 100 },
    );
  });

  it("form posts and string bodies match", async () => {
    await fc.assert(
      fc.asyncProperty(fc.dictionary(word, word, { minKeys: 1, maxKeys: 3 }), async (form) => {
        const opts = { uri: `${base}/form`, method: "POST", form, json: true };
        const [a, b] = [await call(oldRequest, opts), await call(newRequest, opts)];
        expect(b).toEqual(a);
      }),
      { numRuns: 100 },
    );
  });

  it("request.get / request.post helpers behave like the originals", async () => {
    await fc.assert(
      fc.asyncProperty(word, async (seg) => {
        const g = (impl: typeof oldRequest) => new Promise<unknown>((res, rej) => impl.get(`${base}/${seg}`, { json: true }, (e: unknown, r: { statusCode: number }, b: unknown) => (e ? rej(e) : res([r.statusCode, b]))));
        expect(await g(newRequest)).toEqual(await g(oldRequest));
      }),
      { numRuns: 100 },
    );
  });

  it("rejects missing uri like the original", () => {
    expect(() => newRequest({})).toThrow();
    expect(() => oldRequest({})).toThrow();
  });
});
